d=multiply(e,f)*0.5;
//d*=d;
//b*=dot(cross(e,f),normalize(vec3( 1.0 , 1.0 , 1.0 )));//vec3(sin(q3), 1.0 ,cos(q3)));
//ret=ret*vec3( 1.0 ,0.0,0.0)+s*vec3(0.0,0.4,0.9);
//ret*=0.9;
/*ret.xyz=normalize(c)*b.xxx;
ret.x=sin(2.0 * (0.5+1*sin(q4*M_PI_2))*ret.x*M_PI_2+q13*M_PI_2)*0.5+0.5;
ret.y=sin(ret.y*M_PI_2+q7 * 5.0)*0.5+0.5;
*/
/*
ret.x=sin(ret.x*M_PI_2+q3*M_PI_2)*0.5+0.5;
ret.y=sin(ret.y*M_PI_2+q4*M_PI_2)*0.5+0.5;
ret.z=sin(ret.z*M_PI_2+q5*M_PI_2)*0.5+0.5;
*/
//ret=cos(ret*M_PI*0.5); //gamma
//ret=abs(c);
//ret=ret*b.xxx;
//ret=mix(ret,s,b.xxx);
//ret*=ret;
//ret*=ret;
ret=mix(tex2d(sampler_rand01,/*0.5+(uv-0.5)*d*b+vec3(q3,q4)*0.1+0*/
0.5+(uv-0.5)*abs(b*d)), 0.0 ,1.0 - abs(b));  ///ret.zz);
//ret=tex2d(sampler_rand01,ret.xy/(ret.zz + 1.0));
ret=s;
ret.x=sin((ret.x)*M_PI_2*0.5);
ret.y=sin((ret.y)*M_PI_2*0.5);
ret.z=sin((ret.z)*M_PI_2*0.5);
//ret=ret*b;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  sampler sampler_rand01;
shader_body
{
vec3 s = texture(sampler_main,uv).xyz;
vec3 a,b,c,t,d,e,f;
f=multiply(s,rot_f1);
/*s.x=sin(s.x*M_PI_2 * 3.0)*0.5+0.5;
s.y=cos(s.y*M_PI_2 * 3.0)*0.5+0.5;
s.z=sin(s.z*M_PI_2 * 3.0)*0.5+0.5;
*/
//s.xy=s.xy-0.5;
a.xyz=vec3(s.x * 2.0,s.z * 2.0,0.1).xyz;
b.xyz=vec3(0.97,-s.y * 2.0,s.z * 2.0).xyz;
c.xyz=cross(normalize(a),normalize(b)).xyz;
//c.zx=-0.05;
ret=texture(sampler_main,(c.zx*0.01*c.yy)+(uv-0.5)*(0.96+c.yy*0.02)+0.5);//((c.xz * 5.0+(uv-0.5) * 2.0)/(c.yy*c.yy + 8.0))+0.5);
//uv*(b.xx*0.04+0.96));//0.03+0.4*
//ret=ret*pow(2.0 * b.xxx, 3.0 )+ret*b.xxx*b.xxx;
e=multiply(ret,rot_f1);
b=cross(e+f,f);
d=multiply(e,f)*0.5;
//d*=d;
//b*=dot(cross(e,f),normalize(vec3( 1.0 , 1.0 , 1.0 )));//vec3(sin(q3), 1.0 ,cos(q3)));
//ret=ret*vec3( 1.0 ,0.0,0.0)+s*vec3(0.0,0.4,0.9);
//ret*=0.9;
/*ret.xyz=normalize(c)*b.xxx;
ret.x=sin(2.0 * (0.5+1*sin(q4*M_PI_2))*ret.x*M_PI_2+q13*M_PI_2)*0.5+0.5;
ret.y=sin(ret.y*M_PI_2+q7 * 5.0)*0.5+0.5;
*/
/*
ret.x=sin(ret.x*M_PI_2+q3*M_PI_2)*0.5+0.5;
ret.y=sin(ret.y*M_PI_2+q4*M_PI_2)*0.5+0.5;
ret.z=sin(ret.z*M_PI_2+q5*M_PI_2)*0.5+0.5;
*/
//ret=cos(ret*M_PI*0.5); //gamma
//ret=abs(c);
//ret=ret*b.xxx;
//ret=mix(ret,s,b.xxx);
//ret*=ret;
//ret*=ret;
ret=mix(tex2d(sampler_rand01,/*0.5+(uv-0.5)*d*b+vec3(q3,q4)*0.1+0*/
0.5+(uv-0.5)*abs(b*d)), 0.0 ,1.0 - abs(b));  ///ret.zz);
//ret=tex2d(sampler_rand01,ret.xy/(ret.zz + 1.0));
ret=s;
ret.x=sin((ret.x)*M_PI_2*0.5);
ret.y=sin((ret.y)*M_PI_2*0.5);
ret.z=sin((ret.z)*M_PI_2*0.5);
//ret=ret*b;
}
  fragColor = vec4(ret, 1.0);
}

